    "source": "// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {Breadcrumbs, BreadcrumbItem} from '@astryxdesign/core/Breadcrumbs';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {HomeIcon, Cog6ToothIcon} from '@heroicons/react/24/outline';\n\nexport default function BreadcrumbsWithIcons() {\n  return (\n    <Breadcrumbs>\n      <BreadcrumbItem href=\"/\" startIcon={<Icon icon={HomeIcon} size=\"sm\" />}>\n        Home\n      </BreadcrumbItem>\n      <BreadcrumbItem\n        href=\"/settings\"\n        startIcon={<Icon icon={Cog6ToothIcon} size=\"sm\" />}>\n        Settings\n      </BreadcrumbItem>\n      <BreadcrumbItem isCurrent>Profile</BreadcrumbItem>\n    </Breadcrumbs>\n  );\n}\n",
    "demoMediaReplaced": 0,
    "demoContentReplaced": 0
  },
